using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
internal sealed class TransferDraft{public Theme Theme;public Dictionary<string,byte[]> Settings=new Dictionary<string,byte[]>();public byte[] Wallpaper;}
internal static class ThemeTransfer{
 internal static readonly string[] Keys=new[]{"runtime-appearance.txt","ink-text.txt","ink-chat.txt","ink-icons.txt","ink-accent.txt","ink-link.txt","icon-effects.txt","input-glass.txt","input-border.txt","background-effects.txt","background-strength.txt","whole-background.enabled","backdrop-uniform.enabled"}.Concat(new[]{0,1}.SelectMany(m=>AppearanceProfiles.Keys.Concat(new[]{"profile.ready"}).Select(k=>"appearance-"+(m==0?"light":"dark")+"/"+k))).ToArray();
 static byte[] ReadEntry(ZipArchiveEntry e,int max){if(e.Length<0||e.Length>max)throw new InvalidDataException("迁移包条目过大："+e.FullName);using(var s=e.Open())using(var m=new MemoryStream()){var b=new byte[8192];int n;while((n=s.Read(b,0,b.Length))>0){if(m.Length+n>max)throw new InvalidDataException("迁移包解压大小超限。");m.Write(b,0,n);}return m.ToArray();}}
 static void Entry(ZipArchive zip,string name,byte[] data){using(var s=zip.CreateEntry(name,CompressionLevel.Optimal).Open())s.Write(data,0,data.Length);}
 internal static TransferDraft Read(string file){var p=new TransferDraft();using(var zip=ZipFile.OpenRead(file)){var names=new HashSet<string>(StringComparer.Ordinal);if(zip.Entries.Count>Keys.Length+3)throw new InvalidDataException("迁移包包含未知条目。");foreach(var e in zip.Entries){if(!names.Add(e.FullName))throw new InvalidDataException("迁移包条目重复。");if(e.FullName=="format.txt"){string format=Encoding.UTF8.GetString(ReadEntry(e,100));if(format!="WeixinThemeStudio-profile-v1"&&format!="WeixinThemeStudio-profile-v2")throw new InvalidDataException("迁移包格式不支持。");}else if(e.FullName=="theme.json"){using(var m=new MemoryStream(ReadEntry(e,32768))){p.Theme=(Theme)new System.Runtime.Serialization.Json.DataContractJsonSerializer(typeof(Theme)).ReadObject(m);Palette.Validate(p.Theme);}}else if(e.FullName=="wallpaper.png"){p.Wallpaper=ReadEntry(e,NativeBackground.MaxWallpaperBytes);using(var m=new MemoryStream(p.Wallpaper))using(var im=Image.FromStream(m)){if((long)im.Width*im.Height>100000000||im.Width<1||im.Height<1)throw new InvalidDataException("壁纸尺寸超限。");}}else if(e.FullName.StartsWith("settings/",StringComparison.Ordinal)&&Keys.Contains(e.FullName.Substring(9))){string key=e.FullName.Substring(9);byte[] data=ReadEntry(e,8192);string value=Encoding.UTF8.GetString(data).Trim('\uFEFF',' ','\r','\n');if(System.IO.Path.GetFileName(key).StartsWith("ink-")&&value!="original"&&!Palette.IsColor(value)&&!(System.IO.Path.GetFileName(key)=="ink-canvas.txt"&&value=="auto"))throw new InvalidDataException("迁移包包含无效颜色。");p.Settings.Add(key,data);}else throw new InvalidDataException("迁移包包含未知或不允许的路径："+e.FullName);}if(!names.Contains("format.txt")||p.Theme==null)throw new InvalidDataException("迁移包不完整。");}return p;}
 internal static void Export(string file,Theme theme,string store){Palette.Validate(theme);string stage=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var zip=ZipFile.Open(stage,ZipArchiveMode.Create)){Entry(zip,"format.txt",Encoding.UTF8.GetBytes("WeixinThemeStudio-profile-v2"));using(var m=new MemoryStream()){new System.Runtime.Serialization.Json.DataContractJsonSerializer(typeof(Theme)).WriteObject(m,theme);Entry(zip,"theme.json",m.ToArray());}foreach(var key in Keys){if(System.IO.Path.GetFileName(key)=="input-glass.txt")continue;string path=Path.Combine(store,key);if(File.Exists(path))Entry(zip,"settings/"+key,File.ReadAllBytes(path));}string cfg=Path.Combine(store,"background.txt");if(File.Exists(cfg)){string wallpaper=File.ReadAllText(cfg).Trim();string root=Path.GetFullPath(Path.Combine(store,"backgrounds"))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(wallpaper).StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(wallpaper))throw new IOException("当前壁纸不存在，请先重新选图。");Entry(zip,"wallpaper.png",File.ReadAllBytes(wallpaper));}}Read(stage);if(File.Exists(file))File.Replace(stage,file,null);else File.Move(stage,file);}finally{if(File.Exists(stage))File.Delete(stage);}}
 internal static void Commit(TransferDraft p,bool enableBackground=true){string image=null;if(p.Wallpaper!=null){string temp=Path.Combine(Engine.Store,"transfer-wallpaper-"+Guid.NewGuid().ToString("N")+".png");Directory.CreateDirectory(Engine.Store);try{File.WriteAllBytes(temp,p.Wallpaper);image=NativeBackground.CacheImage(temp);}finally{if(File.Exists(temp))File.Delete(temp);}}AutoBackground.SetEnabled(false);AppearanceProfiles.Clear();foreach(string key in Keys){string path=Path.Combine(Engine.Store,key);if(p.Settings.ContainsKey(key)){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,p.Settings[key]);}else if(File.Exists(path))File.Delete(path);}string bg=Path.Combine(Engine.Store,"background.txt");if(image!=null)File.WriteAllText(bg,image,Encoding.UTF8);else if(File.Exists(bg))File.Delete(bg);AppearanceProfiles.EnsureProfiles();AutoBackground.SetEnabled(enableBackground);}
}
internal sealed partial class Studio{
 TransferDraft pendingTransfer;
 void AddTransferControls(Panel p){WorkspaceNote(p,"迁移到另一台 Windows 电脑",0,576,880,28);WorkspaceNote(p,"导出已保存的基础配色、运行时设置和壁纸；不含微信、聊天记录或账号。",0,612,900,32);var export=WorkspaceButton(p,"导出完整迁移包…",0,660,230);var import=WorkspaceButton(p,"导入迁移包…",248,660,230);export.Click+=delegate{try{using(var d=new SaveFileDialog{Filter="主题迁移包 (*.wxtheme)|*.wxtheme",FileName="我的微信主题.wxtheme"})if(d.ShowDialog(this)==DialogResult.OK){ThemeTransfer.Export(d.FileName,Engine.Current(),Engine.Store);status.Text="已导出当前已保存的配色和壁纸；未应用的草稿不在包内。";}}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};import.Click+=delegate{try{using(var d=new OpenFileDialog{Filter="主题迁移包 (*.wxtheme)|*.wxtheme"})if(d.ShowDialog(this)==DialogResult.OK){var draft=ThemeTransfer.Read(d.FileName);Engine.Normalize(File.ReadAllBytes(Engine.Target));pendingTransfer=draft;pendingSmart=null;pendingSmartRestore=false;SelectTheme(draft.Theme);SelectWorkspace("palette");status.Text="迁移包已载入，尚未应用。完全退出微信后点击「应用基础配色」，再正常启动微信。";}}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};p.Height=720;}
}
